def build_final(HUB, V):
    qs = []
    for i, (sec, stem, opts, ans, why) in enumerate(S, 1):
        multi = 'select all' in stem.lower()
        qs.append({'sec': f'{sec} · Final review', 'n': i, 'stem': stem, 'opts': [[l, t] for l, t in zip('abcde', opts)], 'multi': multi, 'ctx': '', 'img': [],
                   'a': {'ans': list(ans), 'why': why, 'cite': f'{sec} — slides, transcript, old exams', 'conf': 'sure', 'scope': 'in'}})
    cs = [card(q) for q in qs]; cs[0] = cs[0].replace('class="card"', 'class="card on"', 1)
    out = deck.page('Exam 3 · Final review exam', f'{len(cs)} questions — one per line of the full review sheet · LC14–LC21, LC23, LC08 · answer out loud, then tap', ''.join(cs), back=HUB)
    out = re.sub(r'← Back to [^<]+', '← Back to Cell Physiology', out, count=1).replace('</style>', XCSS + '</style>', 1).replace('</body>', _copyjs() + '</body>')
    open(FN, 'w').write(out)
    print('final review', len(cs))
    return f'<a class="tile" href="{FN}?v={V}" style="border:3px solid #d94f7f"><div class="emoji">🏁</div><h2>Final review exam</h2><p>{len(cs)} questions · every line of the review sheet · all lectures</p></a>'
